CREATE TABLE IF NOT EXISTS "Application" ("id" TEXT NOT NULL PRIMARY KEY, "serviceSlug" TEXT NOT NULL DEFAULT 'sirket-kurulusu', "applicantName" TEXT NOT NULL, "applicantEmail" TEXT NOT NULL, "applicantPhone" TEXT, "companyName" TEXT, "companyEmail" TEXT, "capital" TEXT, "directorName" TEXT, "companyAddress" TEXT, "naceCodes" TEXT, "partnerAddress" TEXT, "notes" TEXT, "passportKey" TEXT, "criminalRecordKey" TEXT, "utilityBillKey" TEXT, "status" TEXT NOT NULL DEFAULT 'NEW', "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS "Application_status_idx" ON "Application"("status");
